/**
 * Unicode typeface for the President's PDF briefs.
 *
 * jsPDF's built-in Helvetica uses WinAnsiEncoding, which has no naira sign: any
 * line containing ₦ came out corrupted. These two subsets carry the ASCII range
 * plus ₦ — — · ’ … so the money figures render properly, at ~49 KB instead of
 * the 1.5 MB full faces.
 *
 * Source: DejaVu Sans and DejaVu Sans Bold (Bitstream Vera licence — free to
 * redistribute with or without modification), subsetted with fontTools.
 * Loaded lazily, alongside jspdf, so the portal bundle is unaffected until a
 * report is actually built.
 */

export const PDF_FONT_FAMILY = "UPWA Sans";

export const PDF_FONT_REGULAR = "";

export const PDF_FONT_BOLD = "";

export const PDF_FONT_FILES = {
  regular: { vfs: "UPWASans.ttf", base64: PDF_FONT_REGULAR },
  bold: { vfs: "UPWASans-Bold.ttf", base64: PDF_FONT_BOLD },
} as const;
